"""Build a standalone evidence-linked scientific report from completed artifacts."""
from __future__ import annotations

import base64
from html import escape
import json
from pathlib import Path

ROOT = Path('artifacts/encoder_chemistry_20260930')
ARMS = ('parent_1190k', 'periodic_1209k')


def read(path: str):
    return json.loads((ROOT / path).read_text())


def figure(path: str, caption: str) -> str:
    payload=base64.b64encode((ROOT/path).read_bytes()).decode()
    return f'<figure><img src="data:image/png;base64,{payload}" alt="{escape(caption)}"><figcaption>{caption}</figcaption></figure>'


def table(headers: list[str], rows: list[list[str]]) -> str:
    return '<table><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'


def link(path: str, label: str) -> str:
    return f'<a href="{path}">{label}</a>'


def section(number: int, title: str, content: str) -> str:
    return f'<section id="s{number}"><p class="eyebrow">{number:02d}</p><h2>{title}</h2>{content}</section>'


def main():
    probe=read('readout_comparison/comparison.json')['cohorts']['test']
    rows=[]
    for depth,label in ((19,'Block 19 physical tokens'),(27,'Final physical tokens')):
        for group,concept in (('MACCS','MACCS fingerprint'),('functional_groups','Functional groups')):
            p,l=[probe['models'][f'{a}/depth{depth}/attention']['groups'][group]['ensemble']['estimate'] for a in ARMS]
            d=probe['contrasts'][f'checkpoint_depth{depth}_attention']['groups'][group]['ensemble']
            rows.append([label,concept,f'{p:.4f}',f'{l:.4f}',f"{d['estimate']:+.4f} [{d['ci95'][0]:+.4f}, {d['ci95'][1]:+.4f}]"])
    parts=['''<header><p class="eyebrow">Encoder chemistry · checkpoint study · 30 September 2026</p>
<h1>More compressible.<br>No overall chemical improvement demonstrated.</h1>
<p class="lead">The latest periodic-JEPA student contains useful token-level chemical signals and stable SAE features. On this held-out molecular panel, however, token-attention chemistry readouts favor its parent. Sparse reconstruction improves substantially, while chemically selective interpretation remains mixed.</p>
<p>Comparison: periodic student <b>1,209,000</b> versus parent teacher <b>1,190,000</b>. Native JAX activations; sparse autoencoders, feature interventions, layer and head ablations, activation rescue, acquisition-path swaps, and molecular case studies.</p>
<nav><a href="#s1">Comparison</a><a href="#s3">Sparse features</a><a href="#s4">Causal tests</a><a href="#s6">Chemical cases</a><a href="#s8">Reproduction</a></nav></header>''']
    parts.append(section(1,'The token-level comparison', '''<p>The user’s concern about mean pooling is supported: learned token attention recovers additional chemical signal. The parent advantage persists with the same token-aware decoder architecture, three independent readout seeds, and shared molecular folds.</p>'''+table(['Representation','Endpoint · AUROC ↑','Parent','Latest','Latest − parent · paired95% CI'],rows)+'''
<p>These are macro AUROCs of the mean of three seed logits on 1,024 test molecules. MACCS uses 145 supported bits; functional groups use13 supported labels. Targets require at least5 positives and 5 negatives in both training and evaluation. The intervals describe molecule sampling conditional on these checkpoints and fitted probes.</p>
<p>For the latest block 19, attention improves MACCS AUROC by <b>0.0052</b> [0.0035,0.0071] and functional-group AUROC by <b>0.0065</b> [0.0030,0.0100] over mean pooling. The parent ordering also holds among982 test molecules with nonempty Murcko scaffolds absent from the selected training panel. This is evidence about accessible chemical signal under the tested readouts, not an information-theoretic proof that all chemistry has been lost.</p>'''+figure('readout_comparison/readout_auroc.png','Matched physical-token readouts. CLS and invalid peak slots are excluded; learned attention adds four queries (8,192 parameters, approximately 2.13%) to the same classifier.')+link('readout_comparison/comparison.json','Readout results, seed metrics, target support and paired intervals')))
    parts.append(section(2,'What was compared—and how the layers differ', '''<p>The linked W&amp;B run’s latest committed checkpoint is1,209,000; the run stopped with its final log at 1,208,750. Its initialization checkpoint at 1,190,000 initializes the <b>teacher</b>. The periodic student starts fresh and is promoted every 50,000 steps. Therefore this comparison is not simply19,000 additional optimizer steps on the parent weights, and it cannot isolate the causal effect of latent training from the wider recipe.</p>
<p>The encoder has25 blocks,2,048 channels, eight attention heads,127 physical peak slots and a trailing CLS token. Acquisition metadata conditions every block and a final affine transform. Raw block 25, final normalization and final affine output are distinct representations.</p>
<p>Supplemental ridge probes map all 28 extraction depths using mean, max and CLS summaries. Token geometry is measured at eight selected depths. At raw block 19, projected token effective rank is113.6 for the parent and 16.5 for the latest; after final normalization it is3.4 versus 156.1. These are256-dimensional covariance estimates over all 6,144 panel molecules, not test-only estimates or full intrinsic dimension. This strong layer dependence rules out a blanket “rank collapse” description. Single-token m/z decoding remains substantial at block 19 (R²0.800 versus 0.757), showing that observable peak identity survives alongside contextual information.</p>'''+figure('layer_atlas/figures/pooled_chemical_readouts.png','Supplemental layer chemistry atlas. Pooling probes and nuisance baselines supplement the primary token-attention comparison.')+figure('layer_atlas/figures/native_token_geometry.png','Token geometry and input-observable decoding. Depth26 is final normalization; depth 27 is final affine output.')))
    recon=read('sae_reconstruction_comparison.json')['results']
    rr=[]
    for k,seed in ((32,0),(32,1),(64,0)):
        values=[next(x for x in recon if x['encoder']==a and x['k']==k and x['seed']==seed)['quality']['test']['fve_vs_train_mean'] for a in ARMS]
        rr.append([f'TopK{k}, seed{seed}',*(f'{v*100:.2f}%' for v in values)])
    parts.append(section(3,'Sparse autoencoders: reconstruction, chemistry and stability', '''<p>Six native JAX TopK SAEs were trained on valid physical tokens at raw block 19:8,192 features (4× expansion), primary32 active features, a second seed, and a64-active-feature control for each encoder. Chemistry labels are absent from the SAE objective. Train-only normalization and equal total weight per molecule prevent spectra with many peaks from dominating. Each fit used a40-epoch budget; all selected epoch40, so these results are not a convergence claim.</p>'''+table(['Dictionary','Parent · test variance explained','Latest · test variance explained'],rr)+'''
<p>The primary dictionaries explain72.8% versus 89.1% of held-out activation variance. Test nonfiring fractions are1.2% and 6.2%, respectively. <b>Higher sparse reconstruction fidelity shows greater compressibility under this dictionary, not greater chemical meaning.</b></p>
<p>Ten chemical candidates per encoder were frozen using train and validation data: two each for amide, hydroxyl, halide, nitrile and sulfonyl. No amine candidate passed. Random dictionaries and dense-channel maxima were evaluated as baselines; SAE features do not uniformly beat dense channels. All test failures are retained.</p>
<p>Halide features are the most convincing replicated associations: parent f738 test AUROC0.691; latest f7363 AUROC0.675. The latest feature’s activation correlation with its train-aligned replica is0.895 across seeds and 0.833 at k64. Latest sulfonyl f3055 reaches AUROC0.705, but its seed replica reaches0.639 and the second selected sulfonyl feature only 0.568. Averaging both prespecified sulfonyl candidates gives a checkpoint difference whose interval crosses zero. Nitrile candidates largely fail (approximately 0.50–0.54 AUROC), despite stable activations. Hydroxyl features correlate strongly with peak count (Spearman≈0.54). Two latest hydroxyl features map to the same replica, so they are not two independent mechanisms.</p>
<p>Nearest training-molecule chemistry from SAE feature maxima declines over the full bank: Morgan Tanimoto0.1759→0.1671, difference−0.0089 [−0.0127,−0.0049]. Neighbors also become closer in precursor mass. Restricting to identical acquisition categories and fixed5Da/10CE/5-peak calipers leaves472 test molecules with at least two candidates; the Morgan difference becomes−0.0016 [−0.0051,+0.0017]. Both models retain chemical signal within these restricted banks. The full-bank geometry result is partly nuisance-sensitive and does not establish universal chemical degradation.</p>'''+figure('sae_comparison/selected_feature_auroc.png','Frozen SAE feature associations with held-out chemistry, including failed concepts and baseline comparisons.')+figure('sae_comparison/chemical_retrieval.png','Full-bank chemical retrieval from SAE feature activations. Restricted nuisance-matched retrieval is reported separately in the text.')+link('sae_comparison/matched_geometry.json','Matched retrieval and coverage')+' · '+link('sae_reconstruction_comparison.json','All six SAE fits')))
    causal=read('sae_causal_analysis/sae_causal_analysis.json')
    passed=sum(x['holm_adjusted_p']<.05 for x in causal['primary_tests'])
    parts.append(section(4,'What feature interventions actually establish',f'''<p>Each frozen feature was reduced at half and full dose in 512 independent test molecules. The intervention subtracts that feature’s activation times its decoder direction from the original block 19 token, preserving the SAE reconstruction residual. The encoder then runs forward natively. Controls use the <b>same token amplitudes</b> with a firing-matched other-feature direction and an orthogonal random direction. CLS is unchanged. Requested feature/control norms are identical before casting; realized BF16 norms differ slightly. Some latest amide/hydroxyl controls have median mismatches of 3–4% and upper tails around7–8%, so realized controls are approximately rather than exactly norm-matched.</p>
<p>All20 feature removals lower their nominated chemical logits, and <b>{passed}/40</b> full-dose feature-versus-control contrasts pass the prespecified Holm correction. These are causal effects on three fixed chemical readouts. They do not establish chemically specific features: negative molecules and other output labels also change, and some removals slightly improve balanced loss.</p>
<p>Latest halide f7363 links a replicated association (AUROC0.675), measured peak-token activation and a dose-responsive intervention: halide-logit change−0.00509 at half dose and−0.00993 at full dose [−0.01291,−0.00718]. Both direction controls show smaller changes. Yet its removal slightly improves target balanced BCE, so it is influential without being necessary for correct prediction. Latest sulfonyl f3055 has stronger association (AUROC0.705), but its target effect−0.00431 ranks only9th among15 functional-group responses; the direction also affects carboxyl, aldehyde and hydroxyl. These directions influence several chemical outputs.</p><p>A decisive failure example is latest nitrile f3348: its held-out association AUROC is0.496, yet removing it lowers the nitrile logit by 0.0348. Causal decoder influence can coexist with no useful chemical discrimination. No positive feature steering was run: these experiments test removal and dose dependence, not sufficiency to create chemical evidence. Full SAE reconstruction also damages MACCS balanced BCE by 0.0100 for the parent and 0.0113 for the latest, so reconstruction variance alone does not guarantee preservation of task-relevant information.</p>
<p>All19,390 audited physical-token sparse codes per encoder exactly match the exports: zero TopK membership or amplitude changes. Identity patching and inactive-feature edits give exactly zero logit change. Half-dose, positive/negative subgroups and all 188-target effects are reported as secondary analyses; they are not additional corrected discoveries.</p>'''+figure('sae_causal_analysis/sae_feature_effects.png','Held-out causal feature effects with matched-direction controls. Target-logit influence must be interpreted together with association, negative-class effects and other-target responses.')+figure('sae_causal_analysis/sae_target_profiles.png','Other chemical outputs also respond to candidate-feature removal, limiting monosemantic interpretations.')+link('sae_causal_analysis/sae_causal_analysis.json','Full causal feature audit and effect profiles')))
    component=read('component_analysis/summary.json')
    comp_rows=[]
    for arm in ARMS:
        c=component['arms'][arm]
        for kind in ('attention','mlp','head'):
            e=c['largest_observed'][kind]
            comp_rows.append([arm,e['variant'],f"{e['delta']:+.4f} [{e['ci95'][0]:+.4f}, {e['ci95'][1]:+.4f}]"])
    parts.append(section(5,'Where the prediction depends on peaks and metadata', '''<p>Every attention, MLP and block-conditioning branch was screened on 256 validation molecules. The top three layers per branch were frozen before testing512 separate molecules; all eight heads in each selected attention layer were then ablated. Final metadata doses were fixed in advance. The table shows the largest observed test effects within this tested set, a descriptive ranking rather than a second independent selection stage. Branch and head ablations are artificial necessity tests, not additive decompositions of a circuit.</p>'''+table(['Encoder','Largest observed tested component','Change in balanced BCE ·95% CI'],comp_rows)+'''<p>Among the24 heads tested per encoder, the parent has a concentrated late effect at block23/head6 (ΔBCE+0.0385), whereas the latest’s largest observed head effect is block21/head6 (+0.0037), despite a large whole-attention-branch effect. The nonlinear normalization and gating prevent interpreting these differences as additive head contributions. Only validation-selected blocks were tested at head level.</p>'''+figure('component_analysis/component_heads.png','Validation-selected component and head interventions on held-out molecules. Positive balanced BCE change means damage to the fixed readouts.')+'''
<p><b>Activation rescue identifies a token-local route.</b> After attenuating the top20% of peaks, restoring their clean raw states recovers the original readout vector much better than restoring the same number of uncorrupted random slots. At block 19, squared logit error falls from 0.259 to 0.070 for the parent (random0.229), and from 0.281 to 0.067 for the latest (random0.256). Full-state restoration is exactly clean at every depth; restoring the corrupted slots at the input embedding is also exact. Because this corruption has little class-balanced loss damage on the256-molecule patching cohort, chemistry-loss recovery is inconclusive. This localizes transmission of the input perturbation, not a validated fragment circuit.</p>'''+figure('patching_analysis/activation_rescue.png','Clean-state restoration after intensity attenuation. Absolute logit recovery is clear; balanced-loss recovery has broad intervals.')+'''
<p><b>Robustness improves, acquisition invariance does not.</b> Across1,024 test molecules and 177 train-active outputs, top20% peak removal increases ordinary mean BCE by 0.0627 for the parent and 0.0359 for the latest. Clean BCE is0.4437 versus 0.4785; after removal it is0.5064 versus 0.5144. Smaller damage does not reverse the absolute chemistry ranking. Permuted intensities and artificial mass perturbations are reported separately.</p>
<p>Replacing collision energy with an observed value from a true repeat of the same molecule increases BCE by 0.00645 versus 0.01093 on 689 eligible pairs; the excess latest damage is0.00449 [0.00057,0.00863]. The native2×2 path experiment routes old/new metadata through block conditioning and final affine independently using raw25 patching. Block-only damage is0.00651 versus 0.00852; the latest has an additional positive interaction0.00247 [0.00208,0.00286]. Final-affine-only mean BCE change is near zero, yet its score drift grows0.00536→0.01472, so this path is responsive. Actual repeated spectra also show larger chemical-score drift for the latest (0.1007→0.1093 mean absolute sigmoid-score difference).</p>
<p>The repeat cosine metric is cosine between <b>readout logit vectors</b>, not embedding cosine. Six theoretical neutral-loss windows have only 4–54 matched test cases and mixed effects. They provide no confirmed peak-to-fragment mechanism.</p>'''+figure('input_effects_analysis/metadata_paths.png','Observed collision-energy path swaps. Both diagonal self-patches are exact; all other acquisition fields are held fixed in these selected pairs.')+figure('input_effects_analysis/input_robustness.png','Input corruption responses on the full test panel. These ordinary BCE summaries use177 train-active outputs and differ from class-balanced causal summaries.')))
    parts.append(section(6,'Chemical cases, including false positives', '''<p>The <a href="feature_atlas.html"><b>standalone feature atlas</b></a> contains eight cards and 16 molecular examples with RDKit structures, SMARTS-highlighted atoms, measured processed spectra and exact physical-slot SAE activations. It covers stable halide, variable sulfonyl, failed nitrile and count-associated hydroxyl features from both encoders. The highlighted atoms establish a molecular label; they do not assign a measured peak to an atom or fragment.</p>
<p>Each card shows the highest-activation positive and negative test example after feature selection and confirmation were frozen. All negative examples cross the validation threshold: they are real false positives. The selection is deterministic and explicitly illustrative, not new independent validation.</p>
<p>A separate32-case list was fixed before the input analysis. All six held-out concept-pair cases are shown: outcomes are mixed. C04’s amine-absent donor improves; C08’s halide ordering improves but the absent donor remains high; C10’s sulfonyl ordering reverses unfavorably; C12’s nitrile pair remains misordered. Case C21’s exact preset repeat is unavailable in the sweep and is marked missing rather than replaced; its raw energy values also clip to the same native input. Only three strict held-out isomer pairs exist, insufficient for a broad isomer claim.</p>'''+figure('input_effects_analysis/prespecified_chemical_cases.png','Prespecified held-out chemical pairs, retained regardless of outcome.')+figure('sae_causal_analysis/sae_chemical_cases.png','Fixed-feature causal case illustrations, including a nitrile failure. Readout changes alone do not prove a selective chemical mechanism.')+link('panel/case_candidates.json','Prespecified case list')+' · '+link('feature_atlas/selection.json','Post-confirmation illustration selection')))
    parts.append(section(7,'Evidence quality and limits', '''<p>The6,144-molecule panel contains 4,096 training,1,024 validation and 1,024 test connectivity identities drawn from the official MassSpecGym1.5 folds, one representative spectrum per identity. Identity and SMILES mismatches were excluded at group level; the source and selected arrays are hashed. Labels comprise166 MACCS bits, seven elements and 15 SMARTS functional groups. True repeat pairs require full InChIKey and canonical isomeric SMILES equality. No measured peak-fragment ground truth is available.</p>
<p>The analysis preserves the native JAX BF16 forward graph, physical slots and masks. Both cached activation sets are bitwise equal to their native batch8 pilots. This matters: the latest native batch16 output differs by 2.585% relative L2 from batch8, and exported PyTorch float32-residual execution also differs despite identical checkpoint weights. Initial batch16 products are archived and excluded from primary evidence. Full traces and separately compiled decoders prevent output pruning or fusion from silently changing the encoder computation. Cross-job decoder arithmetic can differ by approximately 1.9×10⁻⁶; paired interventions run within one graph.</p>
<p>Important limits: there are only two fixed pretraining checkpoints; probe-seed replication does not estimate training-recipe uncertainty. Existing benchmark test molecules have been used in earlier studies, and encoder pretraining overlap is not established. Within this study, feature/component discovery uses train and validation before test. Matched donor pairs reuse molecules and are observational controls, not chemical counterfactuals. Rare chemistry, especially thiol, aldehyde, phosphorus and phosphate, cannot support broad conclusions. Confidence intervals are descriptive unless explicitly covered by the40-test SAE Holm family; bootstrap groups with a missing class are omitted rather than changing target sets.</p>
<p>The study supports a concrete mechanistic account of tested signal paths and several feature effects. Head-to-feature mediation was not tested. It does not provide a complete decomposition of all encoder parameters, a uniquely identified minimal circuit, or atom-resolved fragmentation explanations. On the present evidence I would keep the parent as the chemical-representation reference, retain token-attention evaluation, and require stronger nuisance-controlled and independently held-out chemistry before claiming that this latent-training run improves semantic alignment.</p>'''))
    parts.append(section(8,'Reproduction and artifact map', '''<p>All analysis uses the repository’s existing virtual environment and native JAX backend. No production training changes were made for this study. Large lossless token caches, SAE dictionaries and checkpoints reside on Modal volume <code>spectra-massspecgym-maccs-probe</code>, directory <code>/results/encoder_chemistry_20260930</code>; the parent checkpoint is under <code>/results/salt_mechanisms_20260919/checkpoints/1190000</code>. Local JSON files record source, input, checkpoint, cache, readout and selection hashes.</p>
<pre>.venv/bin/python scripts/prepare_encoder_chemistry_panel.py --help
.venv/bin/python -m modal run scripts/modal_encoder_chemistry.py --help
.venv/bin/python -m modal run scripts/modal_encoder_chemistry_probes.py --help
.venv/bin/python -m modal run scripts/modal_encoder_chemistry_sae.py --help
.venv/bin/python -m modal run scripts/modal_encoder_chemistry_sae_causal.py --help
.venv/bin/python scripts/analyze_encoder_chemistry_patching.py
.venv/bin/python scripts/write_encoder_chemistry_report.py</pre>
<p>The <code>--help</code> commands expose phase-specific rebuild options; rebuilding remote stages allocates GPU compute. The exact invocation logs, native source snapshots, saved hyperparameters and frozen selections accompany each stage. This report can be regenerated from the completed local artifacts; it embeds its figures for standalone reading, while detailed JSON/atlas links use neighboring files.</p>'''+table(['Evidence','Artifact'],[
['Checkpoint pinning',link('endpoint_selection.json','GCS object generations and checksums')],
['Panel identity and folds',link('panel/manifest.json','Panel manifest')+' · '+link('panel/validation.json','Validation')],
['Primary readouts',link('readout_comparison/comparison.json','Metrics and contracts')],
['Sparse features',link('sae_comparison/comparison.json','Chemical associations and geometry')],
['Causal features',link('sae_causal_analysis/sae_causal_analysis.json','Interventions, controls and tests')],
['Input and metadata',link('input_effects_analysis/results.json','Full results')],
['Components and rescue',link('component_analysis/summary.json','Components')+' · '+link('patching_analysis/results.json','Activation rescue')],
['Completion audit',link('study_protocol.json','Requirement ledger')+' · '+link('completion_audit.json','Independent artifact audit')],
])+'''<p>Methods informed by <a href="https://arxiv.org/abs/2406.04093">Gao et al., Scaling and evaluating sparse autoencoders</a>, <a href="https://arxiv.org/abs/2309.16042">Zhang &amp; Nanda, activation-patching methodology</a>, and <a href="https://arxiv.org/abs/2409.14507">feature splitting and absorption analysis</a>. The implemented TopK training adapts the dead-feature threshold to this smaller token budget; it is not an exact replication of the large-scale paper setup.</p>'''))
    css='''body{margin:0;background:#faf9f6;color:#20313a;font:17px/1.62 Georgia,serif}main{max-width:1080px;margin:auto;padding:54px 34px}header{border-bottom:3px solid #227d88;padding-bottom:35px}h1{font:600 46px/1.12 Arial,sans-serif;letter-spacing:-1.4px;max-width:900px}h2{font:600 29px/1.2 Arial,sans-serif;margin-top:0}p{max-width:960px}.lead{font-size:22px;line-height:1.48}.eyebrow{font:600 12px/1.4 Arial,sans-serif;text-transform:uppercase;letter-spacing:1.8px;color:#267684}section{padding:30px 0;border-bottom:1px solid #cbd4d6}nav{display:flex;gap:22px;flex-wrap:wrap;font:14px Arial,sans-serif}a{color:#0a667d}table{width:100%;border-collapse:collapse;margin:25px 0;font:14px/1.5 Arial,sans-serif}th{text-align:left;background:#e9efef}td,th{padding:11px;border-bottom:1px solid #d5dddd;vertical-align:top}figure{margin:30px 0;background:white;padding:12px}img{width:100%;height:auto}figcaption{font:13px/1.5 Arial,sans-serif;color:#4a626c;padding:8px 12px}pre{font:12px/1.6 monospace;white-space:pre-wrap;background:#edf0ef;padding:20px}code{font-size:.85em;overflow-wrap:anywhere}@media(max-width:700px){main{padding:25px 18px}h1{font-size:34px}table{font-size:11px}td,th{padding:6px}}@media print{main{padding:0}section{break-before:auto}figure,table{break-inside:avoid}nav{display:none}}'''
    html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Encoder chemistry: parent vs periodic JEPA</title><style>'+css+'</style><main>'+''.join(parts)+'</main></html>'
    (ROOT/'report.html').write_text(html)
    print(ROOT/'report.html')


if __name__=='__main__':
    main()
